/// <summary>
///    AVA <c>afterKCS_KBVBuildingProjectCreation</c> method.
/// </summary>
void afterKCS_KBVBuildingProjectCreation()
{
    if (frmCreateBPOK)
    {
        if(frmKCS_KBVBuildingProjectTableCreated.RecId)
        {
            // No research() because this causes loop on datasource.executeQuery()
            //KCS_KBVBuildingProjectTable_ds.research();
            KCS_KBVBuildingProjectTable_ds.positionToRecord(frmKCS_KBVBuildingProjectTableCreated);
            //KCS_KBVBuildingProjectTable_ds.last();
        }

        if (frmCreateBPOKAndNewRequest)
        {
            //element.createRequest();

            TabPageKCS_DirProductGroup.setFocus();
        }      

        frmCreateBPOK               = false;
     //   frmCreateBPOKAndNewRequest  = false;
        frmKCS_KBVBuildingProjectTableCreated.clear();
    }
}

/// <summary>
///    AVA <c>afterKCS_KBVRequestCreation</c> method.
/// </summary>
void afterKCS_KBVRequestCreation()
{
    appl.company(frmDataAreaId);

    if (frmCreateRequestOK)
    {
        if(frmKCS_KBVRequestTableCreated.RecId)
        {
            KCS_KBVRequestTable_DS.research();
            if (!frmCreateBPOKAndNewRequest)
            {
                TabPageKCS_KBVRequestTable.setFocus();
            }

            //KCS_KBVRequestTable_ds.findRecord(frmKCS_KBVBuildingProjectTableCreated);

            if(frmKCS_KBVBuildingProjectTableBeforeCreateRequest.RecId)
            {
                if(KCS_KBVBuildingProjectTable::find(frmKCS_KBVRequestTableCreated.KCS_KBVBuildingProjectID).KCS_KBVStatus != frmKCS_KBVBuildingProjectTableBeforeCreateRequest.KCS_KBVStatus)
                {
                    KCS_KBVBuildingProjectTable_DS.reread();
                }
                frmKCS_KBVBuildingProjectTableBeforeCreateRequest.clear();
            }
            else if(frmKCS_KBVRequestTableCreated.RecId)
            {
                KCS_KBVBuildingProjectTable_DS.reread();
            }
        }
        frmCreateRequestOK = false;
        frmKCS_KBVRequestTableCreated.clear();
    }
}

