/// <summary>
///    AVA <c>createRequest</c> method.
/// </summary>
void createRequest()
{
    Args                argsCreate;
    FormRun             formRunCreate;
    KCS_KBVRequestTable newKCS_KBVRequestTable;
    DataAreaId          localDataArea;
    /*
    int                 i;
    DictTable           dictTable = new DictTable(tableNum(KCS_KBVRequestTable));
    boolean             lDoRicoKalkPublicate;
    */

    if (KCS_KBVBuildingProjectTable.KCS_KBVStatus == KCS_KBVStatus::Locked)
    {
        warning("@NDX:NXARequestForLockedBPNotPossible");
        return;
    }

    argsCreate = new Args();
    argsCreate.caller(this);
    argsCreate.name(formstr(AVAKBVCreateRequestTable));
    argsCreate.parm(KCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
    argsCreate.record(KCS_KBVBuildingProjectTable);

    formRunCreate = classFactory.formRunClass(argsCreate) as FormRun;
    formRunCreate.init();
    formRunCreate.run();
    formRunCreate.wait();

    if(formRunCreate.closedOk())
    {
        newKCS_KBVRequestTable  = formRunCreate.parmKCS_KBVRequestTable();
        localDataArea           = formRunCreate.selectedDataAreaId();

        changecompany(localDataArea)
        {

            KCS_KBVRequestTable.clear();
            /* used buf2buf to copy buffer without system fields
            for(i = 1; i <= dictTable.fieldCnt(); i++)
            {
                if(     dictTable.fieldCnt2Id(i) == fieldNum(KCS_KBVRequestTable, RecId)
                    ||  dictTable.fieldCnt2Id(i) == fieldNum(KCS_KBVRequestTable, DataAreaId)
                    ||  dictTable.fieldCnt2Id(i) == fieldnum(KCS_KBVRequestTable, KCS_KBVRequestId) )
                {
                    continue;
                }
                KCS_KBVRequestTable.(dictTable.fieldCnt2Id(i)) = newKCS_KBVRequestTable.(dictTable.fieldCnt2Id(i));
            }
            */

            Buf2Buf(newKCS_KBVRequestTable, KCS_KBVRequestTable);
            KCS_KBVRequestTable.KCS_KBVRequestID        = '';
            KCS_KBVRequestTable.insert();

            newKCS_KBVRequestTable.RecId               = KCS_KBVRequestTable.RecId;

            if(formHasMethod(formRunCreate, 'createIoRs'))
            {
                formRunCreate.createIoRs(KCS_KBVRequestTable.KCS_KBVRequestID, KCS_KBVRequestTable.KCS_KBVBuildingProjectID);
            }
        }

        //Anfragenabhängige Daten neu darstellen
        KCS_KBVRequestTable_ds.research();
        //KCS_KBVRequestTable_ds.findRecord(newKCS_KBVRequestTable);
        KCS_KBVRequestTable_ds.positionToRecord(newKCS_KBVRequestTable);

        /// NDX PaffH 09.02.24  -->
        boolean lDoRicoKalkPublicate;
        [lDoRicoKalkPublicate] = nDXKBVBuildingProject2RicoKalk.doRicoKalkPublicate(KCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
        nDXKBVBuildingProject2RicoKalk.parmLRicoRequest(lDoRicoKalkPublicate);
        /// NDX PaffH 09.02.24  <--

    }
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    frmHCMWorkerRecId       = HcmWorkerLookup::currentWorker();
    frmToday                = AVAKBVBuildingProjectHelper::getToday();
    frmDataAreaId           = CompanyInfo::find().DataArea; //curExt();

    super();
    if (element.args().caller() && 
       (element.args().caller().name() == formStr(AVAKBVCreateBuildingProjectTable)
     || element.args().caller().name() == formStr(AVAKBVCreateRequestTable)) && element.args().parm() == 'CreateFromSearch')
    {
        KCS_KBVBuildingProjectTable_ds.query().dataSourceTable(tableNum(KCS_KBVBuildingProjectTable)).clearDynalinks();
    }

    this.addFilterPaneRanges();
    /// NDX PaffH 09.02.24  -->
    nDXKBVBuildingProject2RicoKalk = NDXKBVBuildingProject2RicoKalk::construct();
    /// NDX PaffH 09.02.24  <--
}

/// <summary>
///    AVA <c>addFilterPaneRanges</c> method.
/// </summary>
public void addFilterPaneRanges()
{
    QueryBuildDataSource kcs_KBVBuildingProjectTableQBDS;

    kcs_KBVBuildingProjectTableQBDS = KCS_KBVBuildingProjectTable_DS.query().dataSourceName(KCS_KBVBuildingProjectTable_DS.name());

    SysQuery::findOrCreateRange(kcs_KBVBuildingProjectTableQBDS, fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID));
    SysQuery::findOrCreateRange(kcs_KBVBuildingProjectTableQBDS, fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVStatus));
    SysQuery::findOrCreateRange(kcs_KBVBuildingProjectTableQBDS, fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVChaser));
    SysQuery::findOrCreateRange(kcs_KBVBuildingProjectTableQBDS, fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVSubject));
    kcs_KBVBuildingProjectTableQBDS.addRange(fieldNum( KCS_KBVBuildingProjectTable,KCS_KBVSubject));
}

