/// <summary>
/// designed from AVA
/// </summary>
public void run()
{

    super();
    if (element.args().caller() 
    &&  (element.args().caller().name() == formStr(AVAKBVCreateBuildingProjectTable)
       || element.args().caller().name() == formStr(AVAKBVCreateRequestTable)) && element.args().parm() == 'CreateFromSearch')
    {
        frmKCS_KBVBuildingProjectTableCreated = element.args().record();
        if (frmKCS_KBVBuildingProjectTableCreated)
        {
            frmCreateBPOK = true;
            frmCreateBPOKAndNewRequest = true;

            KCS_KBVBuildingProjectTable_ds.positionToRecord(frmKCS_KBVBuildingProjectTableCreated);
            element.afterKCS_KBVBuildingProjectCreation();
        }

    }
    if (element.args().caller() && 
        element.args().caller().name() == formStr(AVAKBVCreateRequestTable))
    {
        TabPageKCS_DirProductGroup.setFocus();
    }
}

