/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    Args                    locArgs;
    Query                   locQuery;
    QueryBuildDataSource    locQbds;
    QueryBuildDataSource    locQbdsBase;
    QueryBuildRange         locQbr;
    //QueryBuildRange         locQbr2;


    HcmWorkerRecId          locHCMWorkerRecId;
    Date                    locToday;

    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    smmBusRelTable          locSmmBusRelTable;

    super();

    locQuery            = this.query();
    locHCMWorkerRecId   = HcmWorkerLookup::currentWorker();
    locHCMWorkerRecId   = HcmWorker::userId2Worker(curUserId());
    locToday            = AVAKBVBuildingProjectHelper::getToday();
    /*  sort KCS_KBVBuildingProjectID descending KCS_KBVBuildingProjectTable data source Start position to default First
    this.queryBuildDataSource().sortClear();
    this.queryBuildDataSource().addSortField(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID), SortOrder::Descending);
    */
    if(element.args())
    {
        locArgs     = new Args();
        locArgs     = element.args();
        locCommon   = locArgs.record();

        if (locArgs.menuItemType() == MenuItemType::Display)
        {
            switch (locArgs.menuitemName())
            {
                case menuItemDisplayStr(AVAKBVBuildingProjectTable):
                    break;

                case menuItemDisplayStr(AVAKBVBuildingProjectTableAllActive):
                    locQbr      = locQuery.dataSourceTable(tableNum(KCS_KBVBuildingProjectTable)).addRange(fieldNum (KCS_KBVBuildingProjectTable, KCS_KBVClosedDate));
                    locQbr.value(queryValue(dateNull()));
                    break;

                case menuItemDisplayStr(AVAKBVBuildingProjectTableMyFollowing):
                    locQbds     = locQuery.dataSourceTable(tableNum(KCS_KBVBuildingProjectTable));
                    locQbr      = locQbds.addRange(fieldNum (KCS_KBVBuildingProjectTable, KCS_KBVChaser));
                    locQbr.value(queryValue(locHCMWorkerRecId) + ',' + SysQuery::valueNot(0));
                    break;

                case menuItemDisplayStr(AVAKBVBuildingProjectTableMyResponsibility):
                    locQbdsBase = locQuery.dataSourceTable(tableNum(KCS_KBVBuildingProjectTable));
                    locQbds     = locQbdsBase.addDataSource(tableNum(KCS_KBVResponsibilitiesTable));
                    locQbds.addLink(fieldNum (KCS_KBVResponsibilitiesTable, KCS_KBVBuildingProjectID),
                                    fieldNum (KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID)    );
                    locQbds.joinMode(JoinMode::InnerJoin);
                    locQbr      = locQbds.addRange(fieldNum (KCS_KBVResponsibilitiesTable, smmWorker));
                    /*
                    locQbr.value(strfmt('((%1.%2 == %3) && (%1.%2 != %4))', locQbds.name(),
                                                                            fieldstr(KCS_KBVResponsibilitiesTable, smmWorker),
                                                                            queryValue(locHCMWorkerRecId),
                                                                            queryValue(0)                                       )   );
                    */
                    locQbr.value(queryValue(locHCMWorkerRecId) + ',' + SysQuery::valueNot(0));
                    /*
                    // leads to OR-construct
                    locQbr      = locQbds.addRange(fieldNum (KCS_KBVResponsibilitiesTable, smmWorker));
                    locQbr.value(queryValue(locHCMWorkerRecId));
                    locQbr      = locQbds.addRange(fieldNum (KCS_KBVResponsibilitiesTable, smmWorker));
                    locQbr.value(SysQuery::valueNot(0));
                    */
                    break;

                case menuItemDisplayStr(AVAKBVBuildingProjectTableLocalRequests):
                    locQbdsBase = locQuery.dataSourceTable(tableNum(KCS_KBVBuildingProjectTable));
                    locQbds     = locQbdsBase.addDataSource(tableNum(KCS_KBVRequestTable));
                    locQbds.joinMode(JoinMode::ExistsJoin);
                    locQbds.addLink(fieldNum (KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID),
                                    fieldNum (KCS_KBVRequestTable, KCS_KBVBuildingProjectID),
                                    locQbdsBase.name()  );
                    locQbr      = locQbds.addRange(fieldNum (KCS_KBVRequestTable, dataAreaId));
                    locQbr.value(queryValue(frmDataAreaId));
                    break;

                case menuItemDisplayStr(AVAKBVBuildingProjectTableAllSubordinated):
                    if(locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
                    {
                        locKCS_KBVBuildingProjectTable = locCommon;
                        locQbds     = locQuery.dataSourceTable(tableNum(KCS_KBVBuildingProjectTable));
                        locQbr      = locQbds.addRange(fieldNum (KCS_KBVBuildingProjectTable, KCS_KBVParentBuildingProjectID));
                        locQbr.value(queryValue(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID));
                        /*
                        locQbds.clearRanges();
                        locQbds.clearDynalinks();
                        locQbr      = locQbds.addRange(fieldNum (KCS_KBVBuildingProjectTable, KCS_KBVParentBuildingProjectID));
                        locQbr.value(queryValue(locKCS_KBVBuildingProjectTable.KCS_KBVParentBuildingProjectID));
                        */
                    }
                    break;

                case menuItemDisplayStr(AVAKBVBuildingProjectTableSmmBusRelTable):
                    locSmmBusRelTable = locCommon;
                    if(locSmmBusRelTable.RecId)
                    {
                        locQbdsBase = locQuery.dataSourceTable(tableNum(KCS_KBVBuildingProjectTable));
                        locQbds     = locQbdsBase.addDataSource(tableNum(AVABPRelationsToBVRequestDirPartyIdView));
                        locQbds.joinMode(JoinMode::ExistsJoin);
                        locQbds.addLink(fieldNum (KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID),
                                        fieldNum (AVABPRelationsToBVRequestDirPartyIdView, KCS_KBVBuildingProjectID),
                                        locQbdsBase.name()  );
                        locQbr      = locQbds.addRange(fieldNum (AVABPRelationsToBVRequestDirPartyIdView, DirPartyId));
                        locQbr.value(queryValue(locSmmBusRelTable.Party));
                    }
                    break;
            }
        }
    }
}

