/// <summary>
///    AVA <c>editContactPersonName_KCS_KBVRelationsToBV</c> method.
/// </summary>
/// <param name="_set">
///    <c>boolean</c> as type
/// </param>
/// <param name="_record">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_name">
///    <c>ContactPersonName</c> as type
/// </param>
/// <returns>
///    <c>ContactPersonName</c> as return value
/// </returns>
edit ContactPersonName editContactPersonName_KCS_KBVRelationsToBV(  boolean                 _set, 
                                                                    KCS_KBVRelationsToBV    _record,
                                                                    ContactPersonName       _name)
{
    ContactPersonName   retVal;

    if (_set)
    {
        AVAKBVDirPartyContactPersonHelper   locAVAKBVDirPartyContactPersonHelper;

        locAVAKBVDirPartyContactPersonHelper = new AVAKBVDirPartyContactPersonHelper();

        locAVAKBVDirPartyContactPersonHelper.parmSet(_set);
        locAVAKBVDirPartyContactPersonHelper.parmDataAreaId(frmDataAreaId);
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyId(Grid_KCS_KBVRelationsToBV_DirPartyId.value());
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyName('');
        //locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(Grid_KCS_KBVRelationsToBV_ContactPersonId.valueStr());
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(_name);
        //locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(_name);
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(ContactPerson::find(_name).personName());

        retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonName();
        // get DirPartId to ContactPerson if not set
       // retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonNameModified();

        Grid_KCS_KBVRelationsToBV_DirPartyId.value(locAVAKBVDirPartyContactPersonHelper.parmDirPartyId());
        Grid_KCS_KBVRelationsToBV_ContactPersonId.Text(locAVAKBVDirPartyContactPersonHelper.parmContactPersonId());
        Grid_KCS_KBVRelationsToBV_editContactPersonName.text(locAVAKBVDirPartyContactPersonHelper.parmContactPersonName());
        KCS_KBVRelationsToBV.DirPartyId         = locAVAKBVDirPartyContactPersonHelper.parmDirPartyId();
        KCS_KBVRelationsToBV.ContactPersonId    = locAVAKBVDirPartyContactPersonHelper.parmContactPersonId();
        KCS_KBVRelationsToBV.ContactPersonParty = ContactPerson::find(KCS_KBVRelationsToBV.ContactPersonId).Party;
        /*
        if(locAVAKBVDirPartyContactPersonHelper.parmRefresh())
        {
            if (FormDataUtil::getFormDataSource(this))
            {
            FormDataUtil::getFormDataSource(this).refresh();
            }
            //element.redraw();
        }
        */
    }
    else
    {
        if (_record.ContactPersonId)
        {
            retVal = ContactPerson::find(_record.ContactPersonId).personName();
        }
        else if (_record.ContactPersonParty)
        {
            retVal = ContactPerson::findByPartyRecId(_record.ContactPersonParty).personName();                
        }
        if (!retVal)
        {
            retVal = DirPerson::find(_record.ContactPersonParty).Name;
        }
    }

    return retVal;

}

