/// <summary>
///    AVA <c>executeQuery</c> method.
/// </summary>
public void executeQuery()
{
    Query                       locQuery;
    QueryBuildDataSource        locQbds;
    QueryBuildRange             locQbr;
    str                         queryCondition;

    locQuery                    = this.query();

    if(frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID)
    {
        queryCondition  = '((%1.%2 = \"%4\") || (%1.%3 = \"%4\"))';
    }
    else
    {
        queryCondition  = '((%1.%2 = %4) || (%1.%3 = %4))';
    }
    locQbds         = locQuery.dataSourceTable(tableNum(AVAConnectionBPToBP));
    locQbds.clearRanges();
    locQbds.clearDynalinks();
    locQbr          = locQbds.addRange(fieldNum (AVAConnectionBPToBP, KCS_KBVBuildingProjectIDA));
    queryCondition  = strFmt(   queryCondition,
                                locQbds.name(),
                                fieldStr(AVAConnectionBPToBP, KCS_KBVBuildingProjectIDA),
                                fieldStr(AVAConnectionBPToBP, KCS_KBVBuildingProjectIDB),
                                queryValue(frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID)   );
    locQbr.value(queryCondition);

    super();
}

